UPDATE companies SET description='Green Mountain Furniture has operated in Ossipee, New Hampshire, since 1975.

The company functions as a full-line furniture retailer rather than a manufacturer. Its showroom stocks living-room, bedroom, dining, home-office, and cabin-style collections from brands such as Craftmaster, Flexsteel, and Best Home, along with mattresses (innerspring, memory foam, and latex), adjustable bases, area rugs, lighting, and decorative accessories. A delivery team also provides removal of existing pieces at the time of drop-off.

Shoppers can browse dozens of recliners, sofas, and beds without pressure from commission-based staff.

The founder''s original pitch — “more than meets the eye” — still frames the value proposition: a large, low-pressure showroom where customers can physically test products, backed by a 100-night sleep trial on mattresses and a five-year Guardsman stain warranty on upholstery.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Delivery and removal services", "Non-commission sales consultation", "100-night mattress comfort trial", "5-year stain warranty administration"], "industries": ["Residential furniture", "Healthcare/accessibility furniture"], "materials": ["Fabric", "Leather", "Wood", "Innerspring", "Memory foam", "Latex", "Medical-grade vinyl"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["40,000 sq ft multi-floor showroom", "Non-commission sales staff", "Delivery with old-furniture removal", "100-night mattress sleep trial", "Five-year Guardsman stain warranty"], "facts_used": ["Founded 1975 -> db", "Headquarters Ossipee, New Hampshire -> db", "40,000 sq ft showroom -> /", "Carries Craftmaster, Flexsteel, Best Home brands -> /", "Offers delivery with removal services -> / (capabilities)", "Non-commission sales staff -> /", "100-night sleep guarantee on mattresses -> /", "5-year Guardsman stain warranty -> /", "Medical-grade vinyl lift recliner (Best Home Kenley) -> industries_served", "Sells innerspring, memory foam, latex mattresses -> /", "Named for mountain range in backyard -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Our website is intended to give you a virtual feel for the styles and variety of pieces we carry.", "founded_year": "1975", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='green-mountain-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Moser Engineering operates from a 100,000-square-foot facility in Portland, Indiana. The company was founded in 1986 by Greg Moser, who initially launched the business to support his own drag-racing habit at the Muncie strip. Today it remains family owned and operated.

The shop produces custom axles, complete rear-end assemblies, housing service parts, differential options, brake packages, and chassis/suspension components. All manufacturing — forging, heat treating, and machining — is done in-house using steel sourced exclusively from U.S. mills.

Customers range from weekend racers and project-car builders to professional teams running circle-track and drag cars. Moser supplies custom axle sets for Jeeps and trucks, full-floater rears for oval competition, and turnkey Muscle Pak rear assemblies for high-end builds. The company also offers parts, fluids, and service items through its online catalog.

Moser cites three pillars for its reputation: domestic manufacturing with full process control, a two-business-day turnaround on most custom orders, and validation via an in-house race team that campaigns two rigs and multiple cars. Staff members, many of them longtime racers and builders, test components on the track before they reach the market.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom axle manufacturing", "Complete rear-end assembly", "Forging", "Heat treating", "Machining", "Differential options", "Brake packages", "Chassis/suspension/shocks/springs", "Circle track/oval packages", "GM/Ford/Mopar applications", "Parts/fluids/services", "Housing service parts", "Axle service parts", "Muscle Pak rear assemblies", "Full-floater rear ends", "Custom alloy axles", "Chrome moly full float rear ends", "Junior Dragster axle assemblies", "Ford Economy Third Member built to order", "Moser Complete Rears"], "industries": ["Drag racing", "Circle track racing", "Street rod", "Off-road (Jeep/truck)", "Project car restoration", "Automotive aftermarket"], "materials": ["US steel", "Alloy steel", "Chrome moly"], "equipment": [], "volume": "", "lead_time": "2 business days for custom orders", "tolerances": "", "built_on": ["Made in USA using US steel from US mills", "Custom orders ship in two business days or less", "In-house race team tests components on track before release", "Family owned and operated since 1986", "Controls entire manufacturing process from forging to machining"], "facts_used": ["Founded in 1986 by Greg Moser -> /about", "Headquartered in Portland, Indiana -> /about", "100,000 square foot facility -> /about", "Family owned and operated -> /about", "Makes custom axles, complete rear ends -> /about", "Uses US steel from US mills, forges, heat treats, machines in-house -> /about", "Custom orders ship in two business days or less -> /about", "Maintains own race team with two rigs and multiple cars -> /about", "Staff includes current and former racers, builders, enthusiasts -> /about", "Products for drag racing, circle track, street rods, Jeep, truck -> /about", "40 years of Moser Engineering -> /", "Muscle Pak rear assemblies -> /", "Hi-performance axles & rear end -> /", "Service discounts for military/first responders -> /", "Categories: Axle & Axle Packages, Rear Ends/Housing and Axles, etc. -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We use high-end technology and precision machinery to make custom axles, complete rear ends, and more at our facility in Portland, Indiana.", "founded_year": "1986", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='greg-moser-engineering-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Grillo & Co operates a woodworking workshop in Golden, Colorado, where founder John Grillo creates bespoke furniture on commission. Grillo trained at the Thomas Chippendale International School of Furniture near Edinburgh, Scotland, where his work earned the Richard Demarco Prize and recognition in Furniture & Cabinetmaking Magazine. He is a member of the Fine Furniture Guild and established his practice in Golden after completing his studies.

The company custom designs and hand-builds each piece, using processes that include 3D design visualization, dovetail joinery, parquetry, tambour door construction, and veneering. Projects range from dining tables and writing desks to console tables and record cabinets, all crafted from solid woods such as walnut, maple, cherry, and exotic veneers. The workshop handles every stage from concept to finish, though no facility size or headcount figures are published.

Grillo & Co serves residential and commercial clients seeking one-of-a-kind furniture for homes and workplaces. Past commissions include a walnut coffee table built to exact dimensions, a federal-style writing desk with birds-eye maple accents, a radial dining table with interlocking legs, and a tambour-door record cabinet. Customers work directly with Grillo through home or office visits and receive progress updates throughout the build.

The firm distinguishes itself through Grillo''s award-winning craftsmanship, his training at a world-furniture school, and membership in the Fine Furniture Guild. The bespoke model eliminates supply-chain constraints common among commercial retailers, and clients buy directly from the designer, allowing involvement down to the style of dovetails and choice of materials.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Hand woodworking", "3D design visualization", "Bespoke commission", "Home/office consultation", "Dovetail joinery", "Parquetry", "Tambour door construction", "Veneering", "Wood finishing"], "industries": ["Residential", "Commercial", "Custom furniture"], "materials": ["Walnut", "Maple", "Cherry", "Pepperwood veneer", "Yew wood", "Burl walnut", "Figured cherry", "Birds-eye maple"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom design and hand-made to exact specifications", "Award-winning craftsmanship (Richard Demarco Prize)", "Training at Thomas Chippendale International School of Furniture", "Member of Fine Furniture Guild", "No supply-chain constraints"], "facts_used": ["Workshop in Golden, Colorado -> /", "Founder John Grillo -> /", "John Grillo trained at Thomas Chippendale International School of Furniture -> /about", "Richard Demarco Prize awarded for round dining table -> /about", "Member of Fine Furniture Guild -> /about", "Custom design and hand make each piece to exact specifications -> /", "3D sketches and design visualization -> /services", "Home/office visits offered -> /services", "No supply-chain constraints -> /services", "Materials: walnut, maple, cherry, pepperwood veneer, yew wood, burl walnut, figured cherry, birds-eye maple -> /, /about", "Customer reviews from Spencer P., Kelsey M., Troy F. -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Grillo and Co creates beautiful bespoke furniture for your home or workplace. Operating almost entirely by commission, we custom design and hand make each piece to your exact specifications at our workshop in Golden, Colorado.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='grillo-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Groves Bros. is based in Mineral Wells, Texas, and was established in 2001.

The operation centers on handcrafted fabric production. Each fabric is made by hand, resulting in one-of-a-kind pieces. The company does not disclose facility size, employee count, or annual volume, but the process is rooted in traditional Venetian methods adapted for modern drapery, upholstery, and wall-covering applications.

Groves Bros. serves customers in the interior design and furnishing sectors, specifically those specifying fabrics for drapery, upholstery, and wall covering projects.

The firm''s stated distinction lies in its commitment to handcrafting every fabric, ensuring no two pieces are identical, and in drawing on Venetian textile heritage to create what it calls timeless fabrics.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted fabric production", "Venetian-inspired textile techniques", "Custom fabric design for drapery, upholstery, wall covering"], "industries": ["Interior design", "Upholstery", "Drapery", "Wall covering"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted production ensuring each fabric is unique", "Techniques inspired by Venetian textile traditions", "Made in Mineral Wells, Texas", "Focus on timeless, premier fabrics for drapery, upholstery, and wall covering"], "facts_used": ["Founded in 2001 -> db", "Headquarters in Mineral Wells, Texas -> db, /", "Handcrafted fabrics using Venetian-inspired techniques -> /", "Each fabric is unique -> /", "Serves drapery, upholstery, wall covering projects -> /", "Company name Groves Brothers -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "we craft timeless premier fabrics by hand", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='groves-bros' AND approved AND profile IS NULL;
UPDATE companies SET description='Guerrilla Graphix operates as a small business in the Nob Hill district of Albuquerque, New Mexico. The company sells a diverse selection of over 1,000 gift items to both retail and wholesale customers, and provides a range of decoration and design services.

Its service lineup includes graphic design, branding, pre-press layout, and logo development, alongside custom screen printing, embroidery, and large-format digital printing. Screen printing is performed on-site in Albuquerque on items such as T-shirts, hoodies, hats, bandanas, aprons, tote bags, team jerseys, and uniforms. The company also offers wholesale contract printing services and special pricing for resellers.

Customers include retail shoppers, wholesale buyers, and organizations seeking custom apparel or branded merchandise.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Graphic design", "Custom screen printing", "Embroidery", "Large-format digital printing", "Branding and marketing", "Pre-press layout", "Logo development", "Wholesale contract printing"], "industries": ["Retail giftware", "Apparel", "Wholesale"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Over 1,000 gift items available for retail and wholesale", "Custom screen printing on apparel produced locally in Albuquerque", "Graphic design, branding, and pre-press layout services", "Wholesale pricing for resellers and contract printing services", "Designs spanning artistic, humorous, political, historical, and New Mexico themes"], "facts_used": ["Located in Albuquerque, New Mexico, Nob Hill district -> /", "Over 1,000 gift items for retail and wholesale -> /", "Services: graphic design, custom screen printing, embroidery, large-format digital printing -> /", "Custom screen printing on apparel produced in Albuquerque -> /", "Graphic design, branding, pre-press layout, logo development -> /", "Wholesale pricing for resellers and contract printing services -> /", "Designs span artistic, humorous, topical, political, historical, New Mexico-themed -> /", "Deposit of 50% required to initiate production -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We offer CUSTOM screen printing on T-shirts, hoodies, hats, bandanas, aprons, tote bags, team jerseys, uniforms, and various other apparel items RIGHT HERE IN ALBUQUERQUE!", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='guerrilla-graphix' AND approved AND profile IS NULL;
UPDATE companies SET description='HP Electronics, Inc. was founded in 1983 in Baltimore, Maryland, and operates as a licensed electrical contractor specializing in low-voltage electronic systems, distribution sub-systems, and fiber-optic transport media. The company serves the Maryland and Washington, D.C. region while maintaining a client base that extends nationwide and overseas.

The firm designs, installs, and services professional audio-visual and communication systems. Its service portfolio includes area-of-rescue emergency communication, audio system design and installation, classroom AV systems, synchronized clock and timekeeping networks, control system integration, digital signage, and intercom and paging systems. HP Electronics also provides low-voltage electrical contracting and fiber-optic infrastructure installation. The company has completed projects such as the New Severn Run High School auditorium and stadium, and the Church of the Resurrection.

HP Electronics serves education, healthcare, corporate and commercial, hospitality, government and public sector, entertainment and performance venues, houses of worship, and retail clients. Notable installations include projects for New Severn Run High School and the Church of the Resurrection, demonstrating expertise in educational and worship environments.

The company attributes its growth to a corporate philosophy that makes client satisfaction the most important product it delivers, citing that over 75 percent of new business comes from referrals. Early international work included designing and installing one of the first modern sound systems in mainland China, and the firm aims to be the most sought-after electronic systems contractor in the industry.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Area of Rescue Systems installation", "Audio System Design & Installation", "Classroom AV System design and installation", "Clock & Timekeeping Systems installation", "Control System Integration", "Digital Signage Solutions", "Intercom Systems installation", "Low-voltage electrical contracting", "Fiber-optic transport media installation", "Professional sound system design", "Video system installation", "Communication system integration", "Integrated low voltage control systems"], "industries": ["Education", "Healthcare", "Corporate & Commercial", "Hospitality", "Government & Public Sector", "Entertainment & Performance Venues", "Houses of Worship", "Retail"], "materials": [], "equipment": ["SmartCommand Call Commanders (3200 Series)", "Area of Rescue emergency communication station", "SmartCommand Call Boxes (3300 Series)", "eMH browser-based master clock and messaging system"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Over 75% of new clients come from referrals", "Licensed electrical contractor for low-voltage and fiber-optic systems", "Nationwide and overseas customer base", "Designed one of the first modern sound systems in mainland China", "Customer-service-first philosophy"], "facts_used": ["Founded 1983 -> /about", "Headquarters Baltimore, Maryland -> db", "Licensed electrical contractor specializing in low voltage electronic systems -> /about", "Services: Area of Rescue, Audio, Classroom AV, Clock/Timekeeping, Control Integration, Digital Signage, Intercom -> /services", "Industries served: Education, Healthcare, Corporate, Hospitality, Government, Entertainment, Houses of Worship, Retail -> /services", "Over 75% new clients from referrals -> /about", "Nationwide and overseas customer base -> /about", "Designed/installed one of first modern sound systems in mainland China -> /about", "Projects: New Severn Run High School Auditorium, Church of the Resurrection, New Severn Run High School Stadium -> /", "Featured equipment lines: SmartCommand 3200/3300 Series, eMH master clock -> /services"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "As a licensed electrical contractor specializing in low voltage electronic systems, distribution sub-systems and fiber-optic transport media", "founded_year": "1983", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='h-p-electronics' AND approved AND profile IS NULL;
UPDATE companies SET description='H S Automotive Alabama Inc operates in Enterprise, Alabama, as the U.S. subsidiary of South Korea''s Hwaseung Group. The parent company''s auto parts division has pursued overseas expansion since establishing subsidiaries in the United States, China, India, Europe, and South America, while retaining the number-one domestic market share in Korea.

The facility produces two core product lines: weather strips and automotive hoses. Weather strips are manufactured using a proprietary rubber mixing technology that yields sealing components fitted between vehicle body panels. Automotive hoses are engineered for fluid conveyance in engine, brake, and air-conditioning systems, backed by continuous R&D investment.

Hwaseung emphasizes its unique mixing technology for rubber seals and what it describes as hose technology as key differentiators. The division''s stated goal is to enter the global top three by improving profitability, advancing global localization, and accelerating R&D spending.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Rubber mixing and compounding", "Weather strip extrusion and molding", "Automotive hose assembly (engine, brake, A/C)", "R&D for sealing and fluid systems"], "industries": ["Automotive"], "materials": ["Rubber"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Proprietary rubber mixing technology for weather strips", "World-class automotive hose technology for engine, brake, and A/C systems", "Global localization with subsidiaries in the U.S., China, India, Europe, and South America", "Active R&D investment targeting global top-three market position"], "facts_used": ["Headquarters in Enterprise, Alabama -> db", "Subsidiary of Hwaseung Group -> db", "Products: Weather Strip (rubber sealing) and Automotive Hose (engine, brake, A/C) -> page \"/\"", "Unique mixing technology for rubber sealing -> page \"/\"", "World-class technology for automotive hoses -> page \"/\"", "Overseas subsidiaries in U.S., China, India, Europe, South America -> page \"/\"", "No. 1 domestic market share in Korea -> page \"/\"", "Business hours Mon-Fri 8am-5pm -> page \"/\""], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Hwaseung supplies the best rubber sealing product that goes between the car bodies to customers.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='h-s-automotive-alabama-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='H&H Metal Fabrication has operated from St. Louis, Missouri since 1947, when the Finazzo family began manufacturing light fixtures in the same building that housed the H&H radio shop. The company remained under continuous family ownership for more than seven decades before transitioning in 2019 to women-owned leadership under Carolyn Farrell (President) and Morgan Jarrett (COO), with Kevin Farrell serving as CFO.

The shop specializes in custom metal fabrication built to print, including electrical enclosures, e-houses, and enclosure modification services such as cut-outs, drilling, and threading. A 500-ton, 22-foot press brake anchors the forming capacity at their downtown plant on South 22nd Street, and full in-house painting capabilities support finish requirements. The team handles one-off prototypes as well as repeat production runs for larger assemblies.

Customers range from engineering firms and procurement buyers to electrical contractors and manufacturers. Notable projects include fabricating the attachment mechanism for the Chihuly Blue Chandelier reinstallation at the Missouri Botanical Garden, supplying light housings for the new exterior lighting at St. Louis City Hall, and supporting lighting projects for Villa Lighting Supply across the U.S. and Canada.

