b, updated_at=now() WHERE slug='hpp-food-services-wilmington' AND approved AND profile IS NULL;
UPDATE companies SET description='HTS Fabrication, Inc. was founded in 1993 in Lakeville, Minnesota, where it operates from a facility on Hamburg Avenue. The company began as a solutions provider focused on custom metal fabrication and machine building, staffed by a design team, certified welders, and machine builders.

