UPDATE companies SET description='Horizon Nut Company operates in Lost Hills, California, and was founded in 2007. The business is 100 percent grower-owned, formed by a collective of pistachio farmers who wanted direct control over processing. It began as a processing operation led by a diverse group of industry pioneers, drawing on decades of combined experience in California''s pistachio sector, which produces 99 percent of the U.S. crop.

The company hulls and dries pistachios, managing the full processing chain from harvest to finished product. It currently serves a grower group of 45 family farmers and has set a target of 100 million pounds of annual processing capacity, with aggressive expansion plans to meet rapidly growing demand.

Its customers are pistachio growers throughout California''s Central Valley, particularly family farmers seeking a partner to move their crop from field to market. The grower group itself consists of 45 members who are actively involved in the business, and the company positions itself as a home for "true family farmers" who want dedicated partners.

The cooperative was created to ensure pistachios are processed "the way farmers intended them to be," with a focus on quality that aligns processing incentives with grower interests. Leadership emphasizes that grower experience and innovative leadership create an advantage in delivering high-quality pistachios.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Pistachio Processing", "Hulling", "Drying"], "industries": ["Agriculture"], "materials": ["Pistachios"], "equipment": [], "volume": "Target capacity of 100 million pounds annually", "lead_time": "", "tolerances": "", "built_on": ["100% grower-owned cooperative structure", "Target processing capacity of 100 million pounds annually", "Grower group of 45 family farmers", "Full hulling and drying capabilities in-house"], "facts_used": ["Founded in 2007 -> db", "Headquarters in Lost Hills, California -> db", "100% grower-owned -> page /", "Grower group of 45 family farmers -> page /", "Target processing capacity of 100 million pounds annually -> page /", "Capabilities: Pistachio Processing, Hulling, Drying -> db and page /", "Industry served: Agriculture -> db", "Company is a pistachio processing operation -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Horizon Nut Company is a grower-owned, California grown pistachio processing operation", "founded_year": "2007", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='horizon-nut-company' AND approved AND profile IS NULL;
UPDATE companies SET description='The company began as a full-package fashion service provider offering strategy, design, development, and manufacturing under one roof.

The firm operates a vertically integrated model that takes concepts through creative direction, technical design, pattern making, sourcing, sampling, and prototype development to finished garments and accessories. Production runs range from 150 to 2,000 units, with most items manufactured in its Los Angeles facility while leveraging a global partner network. The company reports working with over 400 domestic and international brands.

Its client base spans activewear, athleisure, contemporary, swimwear, sportswear, and streetwear categories. Customers include emerging fashion brands, independent designers, and in-house creative teams seeking end-to-end production support. The company''s Blueprint Program bundles market research, strategic planning, brand identity, and collection design into a customized process for brands building from scratch.

